fun fibMemo(n: Int): Long {
    val memo = LongArray(n + 1) { -1L }              // -1 means not computed yet

    fun f(i: Int): Long {
        if (i <= 1) return i.toLong()                // base cases
        if (memo[i] != -1L) return memo[i]           // reuse the stored answer
        memo[i] = f(i - 1) + f(i - 2)
        return memo[i]
    }

    return f(n)
}
// Time: O(n)   Space: O(n)   Without the memo this would be O(2^n)

fun fibTab(n: Int): Long {
    if (n <= 1) return n.toLong()
    val dp = LongArray(n + 1)
    dp[0] = 0
    dp[1] = 1
    for (i in 2..n) {
        dp[i] = dp[i - 1] + dp[i - 2]                // each cell comes from earlier cells
    }
    return dp[n]
}
// Time: O(n)   Space: O(n)

fun fibOpt(n: Int): Long {
    var a = 0L                                       // dp[i - 2]
    var b = 1L                                       // dp[i - 1]
    repeat(n) {
        val next = a + b
        a = b
        b = next
    }
    return a
}
// Time: O(n)   Space: O(1)
// Use when dp[i] depends only on a fixed number of previous cells

fun minCoins(coins: IntArray, amount: Int): Int {
    val inf = amount + 1                             // larger than any real answer
    val dp = IntArray(amount + 1) { inf }
    dp[0] = 0                                        // zero coins make amount zero
    for (a in 1..amount) {
        for (c in coins) {
            if (c <= a && dp[a - c] + 1 < dp[a]) {
                dp[a] = dp[a - c] + 1                // use coin c, then solve the remainder
            }
        }
    }
    return if (dp[amount] >= inf) -1 else dp[amount]
}
// Time: O(amount * coins)   Space: O(amount)

fun lengthOfLISFast(nums: IntArray): Int {
    val tails = ArrayList<Int>()                     // tails[k] = smallest tail of an increasing subsequence of length k + 1
    for (x in nums) {
        var lo = 0
        var hi = tails.size
        while (lo < hi) {                            // first position with tails[pos] >= x
            val mid = (lo + hi) / 2
            if (tails[mid] < x) lo = mid + 1 else hi = mid
        }
        if (lo == tails.size) tails.add(x) else tails[lo] = x
    }
    return tails.size
}
// Time: O(n log n)   Space: O(n)
// tails is not the actual subsequence, only its length is correct

fun climbStairs(n: Int): Int {
    if (n <= 2) return n
    var prev2 = 1                                    // ways to reach step i - 2
    var prev1 = 2                                    // ways to reach step i - 1
    for (i in 3..n) {
        val cur = prev1 + prev2                      // arrive by a 1-step or a 2-step
        prev2 = prev1
        prev1 = cur
    }
    return prev1
}
// Time: O(n)   Space: O(1)

fun minCostClimbingStairs(cost: IntArray): Int {
    var a = 0                                        // min cost to stand on step i - 2
    var b = 0                                        // min cost to stand on step i - 1
    for (i in 2..cost.size) {                        // step cost.size is the top
        val next = minOf(b + cost[i - 1], a + cost[i - 2])
        a = b
        b = next
    }
    return b
}
// Time: O(n)   Space: O(1)

fun rob(nums: IntArray): Int {
    var prev2 = 0                                    // best loot up to house i - 2
    var prev1 = 0                                    // best loot up to house i - 1
    for (x in nums) {
        val cur = maxOf(prev1, prev2 + x)            // skip this house, or rob it and use i - 2
        prev2 = prev1
        prev1 = cur
    }
    return prev1
}
// Time: O(n)   Space: O(1)

fun robCircular(nums: IntArray): Int {
    if (nums.size == 1) return nums[0]

    fun robRange(lo: Int, hi: Int): Int {
        var prev2 = 0
        var prev1 = 0
        for (i in lo..hi) {
            val cur = maxOf(prev1, prev2 + nums[i])
            prev2 = prev1
            prev1 = cur
        }
        return prev1
    }

    // the first and last houses are neighbors: skip one of them
    return maxOf(robRange(0, nums.size - 2), robRange(1, nums.size - 1))
}
// Time: O(n)   Space: O(1)

fun numDecodings(s: String): Int {
    if (s.isEmpty() || s[0] == '0') return 0
    var prev2 = 1                                    // dp[0]: one way to decode the empty prefix
    var prev1 = 1                                    // dp[1]: one way to decode the first character
    for (i in 2..s.length) {
        var cur = 0
        if (s[i - 1] != '0') cur += prev1            // single digit 1..9
        val two = s.substring(i - 2, i).toInt()
        if (two in 10..26) cur += prev2              // two digits 10..26
        prev2 = prev1
        prev1 = cur
    }
    return prev1
}
// Time: O(n)   Space: O(1)

fun coinChangeWithCoins(coins: IntArray, amount: Int): List<Int> {
    val inf = amount + 1
    val dp = IntArray(amount + 1) { inf }
    val lastCoin = IntArray(amount + 1) { -1 }       // which coin gave the best answer
    dp[0] = 0
    for (a in 1..amount) {
        for (c in coins) {
            if (c <= a && dp[a - c] + 1 < dp[a]) {
                dp[a] = dp[a - c] + 1
                lastCoin[a] = c
            }
        }
    }
    if (dp[amount] >= inf) return emptyList()
    val used = mutableListOf<Int>()
    var a = amount
    while (a > 0) {
        used.add(lastCoin[a])
        a -= lastCoin[a]
    }
    return used
}
// Time: O(amount * coins)   Space: O(amount)
// Keep a parent or choice array whenever you must return the solution itself

fun change(amount: Int, coins: IntArray): Int {
    val dp = IntArray(amount + 1)
    dp[0] = 1                                        // one way to make zero: use nothing
    for (c in coins) {                               // coins OUTER: each combination is counted once
        for (a in c..amount) {
            dp[a] += dp[a - c]
        }
    }
    return dp[amount]
}
// Time: O(amount * coins)   Space: O(amount)

fun combinationSum4(nums: IntArray, target: Int): Int {
    val dp = IntArray(target + 1)
    dp[0] = 1
    for (t in 1..target) {                           // target OUTER: different orders count separately
        for (n in nums) {
            if (n <= t) dp[t] += dp[t - n]
        }
    }
    return dp[target]
}
// Time: O(target * n)   Space: O(target)
// Swapping the two loops switches between counting combinations and counting permutations

fun wordBreak(s: String, wordDict: List<String>): Boolean {
    val words = wordDict.toHashSet()
    val maxLen = wordDict.maxOfOrNull { it.length } ?: 0
    val dp = BooleanArray(s.length + 1)
    dp[0] = true                                     // empty prefix is always breakable
    for (i in 1..s.length) {
        for (len in 1..minOf(i, maxLen)) {
            if (dp[i - len] && s.substring(i - len, i) in words) {
                dp[i] = true
                break
            }
        }
    }
    return dp[s.length]
}
// Time: O(n * maxLen * maxLen) with substring cost   Space: O(n)

fun lengthOfLIS(nums: IntArray): Int {
    if (nums.isEmpty()) return 0
    val dp = IntArray(nums.size) { 1 }               // dp[i] = LIS length ending at index i
    var best = 1
    for (i in nums.indices) {
        for (j in 0 until i) {
            if (nums[j] < nums[i]) {
                dp[i] = maxOf(dp[i], dp[j] + 1)      // extend the subsequence ending at j
            }
        }
        best = maxOf(best, dp[i])
    }
    return best
}
// Time: O(n²)   Space: O(n)
// Use the O(n log n) version from Template 5 for large inputs

fun maxSubArray(nums: IntArray): Int {
    var cur = nums[0]                                // best sum of a subarray ending here
    var best = nums[0]
    for (i in 1 until nums.size) {
        cur = maxOf(nums[i], cur + nums[i])          // start fresh or extend
        best = maxOf(best, cur)
    }
    return best
}
// Time: O(n)   Space: O(1)

fun maxProduct(nums: IntArray): Int {
    var curMax = nums[0]                             // largest product ending here
    var curMin = nums[0]                             // smallest product ending here (a negative can flip it)
    var best = nums[0]
    for (i in 1 until nums.size) {
        val x = nums[i]
        val a = curMax * x
        val b = curMin * x
        curMax = maxOf(x, a, b)
        curMin = minOf(x, a, b)
        best = maxOf(best, curMax)
    }
    return best
}
// Time: O(n)   Space: O(1)

fun numSquares(n: Int): Int {
    val dp = IntArray(n + 1) { Int.MAX_VALUE }
    dp[0] = 0
    for (i in 1..n) {
        var j = 1
        while (j * j <= i) {
            dp[i] = minOf(dp[i], dp[i - j * j] + 1)   // use the square j * j
            j++
        }
    }
    return dp[n]
}
// Time: O(n * sqrt(n))   Space: O(n)

fun deleteAndEarn(nums: IntArray): Int {
    val maxVal = nums.max()                          // use maxOrNull()!! before Kotlin 1.7
    val points = IntArray(maxVal + 1)
    for (x in nums) points[x] += x                   // total points for choosing value x
    var prev2 = 0
    var prev1 = 0
    for (v in 0..maxVal) {
        val cur = maxOf(prev1, prev2 + points[v])    // taking v forbids v - 1 and v + 1
        prev2 = prev1
        prev1 = cur
    }
    return prev1
}
// Time: O(n + maxVal)   Space: O(maxVal)

fun integerBreak(n: Int): Int {
    val dp = IntArray(n + 1)
    dp[1] = 1
    for (i in 2..n) {
        for (j in 1 until i) {
            // split off j: either stop splitting (i - j) or keep splitting it (dp[i - j])
            dp[i] = maxOf(dp[i], j * (i - j), j * dp[i - j])
        }
    }
    return dp[n]
}
// Time: O(n²)   Space: O(n)

fun maxProfitCooldown(prices: IntArray): Int {
    if (prices.isEmpty()) return 0
    var hold = -prices[0]                            // holding a stock
    var sold = 0                                     // just sold today, so tomorrow is a cooldown
    var rest = 0                                     // holding nothing and free to buy
    for (i in 1 until prices.size) {
        val prevHold = hold
        val prevSold = sold
        val prevRest = rest
        hold = maxOf(prevHold, prevRest - prices[i])         // keep, or buy today
        sold = prevHold + prices[i]                          // sell today
        rest = maxOf(prevRest, prevSold)                     // stay idle, or finish the cooldown
    }
    return maxOf(sold, rest)
}
// Time: O(n)   Space: O(1)

fun numWays(n: Int, k: Int): Int {
    if (n == 1) return k
    var same = k                                     // last two posts have the same color
    var diff = k * (k - 1)                           // last two posts have different colors
    for (i in 3..n) {
        val newSame = diff                           // repeat the color only after a different pair
        val newDiff = (same + diff) * (k - 1)
        same = newSame
        diff = newDiff
    }
    return same + diff
}
// Time: O(n)   Space: O(1)
